import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"可怕的萬聖節 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"可怕的萬聖節 Linux 命令 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"可怕的萬聖節 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"可怕的萬聖節 Linux 命令 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171027 Scary Linux commands for Halloween","title":"可怕的萬聖節 Linux 命令","tag":"201804","desc":""},"relativePath":"201804/20171027 Scary Linux commands for Halloween.md","filePath":"[post].md"}'),c={name:"201804/20171027 Scary Linux commands for Halloween.md"};function h(u,s,m,k,g,b){const e=p("Link");return o(),d("div",null,[s[18]||(s[18]=r(`<h1 id="可怕的萬聖節-linux-命令" tabindex="-1">可怕的萬聖節 Linux 命令 <a class="header-anchor" href="#可怕的萬聖節-linux-命令" aria-label="Permalink to “可怕的萬聖節 Linux 命令”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2017/10/animal-skeleton-100739983-large.jpg" alt=""></p><p>雖然現在不是萬聖節，也可以關注一下 Linux 可怕的一面。什麼命令可能會顯示鬼、巫婆和殭屍的圖像？哪個會鼓勵“不給糖果就搗蛋”的精神？</p><h3 id="crypt" tabindex="-1">crypt <a class="header-anchor" href="#crypt" aria-label="Permalink to “crypt”">​</a></h3><p>好吧，我們一直看到 <code>crypt</code>。儘管名稱不同，crypt 不是一個地窖，也不是垃圾文件的埋葬坑，而是一個加密文件內容的命令。現在，<code>crypt</code> 通常用一個腳本實現，通過調用一個名為 <code>mcrypt</code> 的二進制文件來模擬以前的 <code>crypt</code> 命令來完成它的工作。直接使用 <code>mycrypt</code> 命令是更好的選擇。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcrypt x</span></span>
<span class="line"><span>Enter the passphrase (maximum of 512 characters)</span></span>
<span class="line"><span>Please use a combination of upper and lower case letters and numbers.</span></span>
<span class="line"><span>Enter passphrase:</span></span>
<span class="line"><span>Enter passphrase:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>File x was encrypted.</span></span></code></pre></div><p>請注意，<code>mcrypt</code> 命令會創建第二個擴展名為 <code>.nc</code> 的文件。它不會覆蓋你正在加密的文件。</p><p><code>mcrypt</code> 命令有密鑰大小和加密算法的選項。你也可以再選項中指定密鑰，但 <code>mcrypt</code> 命令不鼓勵這樣做。</p><h3 id="kill" tabindex="-1">kill <a class="header-anchor" href="#kill" aria-label="Permalink to “kill”">​</a></h3><p>還有 <code>kill</code> 命令 - 當然並不是指謀殺，而是用來強制和非強制地結束進程，這取決於正確終止它們的要求。當然，Linux 並不止於此。相反，它有各種 <code>kill</code> 命令來終止進程。我們有 <code>kill</code>、<code>pkill</code>、<code>killall</code>、<code>killpg</code>、<code>rfkill</code>、<code>skill</code>（）讀作 es-kill）、<code>tgkill</code>、<code>tkill</code> 和 <code>xkill</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ killall runme</span></span>
<span class="line"><span>[1] Terminated ./runme</span></span>
<span class="line"><span>[2] Terminated ./runme</span></span>
<span class="line"><span>[3]- Terminated ./runme</span></span>
<span class="line"><span>[4]+ Terminated ./runme</span></span></code></pre></div><h3 id="shred" tabindex="-1">shred <a class="header-anchor" href="#shred" aria-label="Permalink to “shred”">​</a></h3><p>Linux 系統也支持一個名為 <code>shred</code> 的命令。<code>shred</code> 命令會覆蓋文件以隱藏其以前的內容，並確保使用硬盤恢復工具無法恢復它們。請記住，<code>rm</code> 命令基本上只是刪除文件在目錄文件中的引用，但不一定會從磁盤上刪除內容或覆蓋它。<code>shred</code> 命令覆蓋文件的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shred dupes.txt</span></span>
<span class="line"><span>$ more dupes.txt</span></span>
<span class="line"><span>▒oΛ▒▒9▒lm▒▒▒▒▒o▒1־▒▒f▒f▒▒▒i▒▒h^}&amp;▒▒▒{▒▒</span></span></code></pre></div><h3 id="殭屍" tabindex="-1">殭屍 <a class="header-anchor" href="#殭屍" aria-label="Permalink to “殭屍”">​</a></h3><p>雖然不是命令，但殭屍在 Linux 系統上是很頑固的存在。殭屍基本上是沒有完全清理掉的死亡進程的遺骸。進程_不應該_這樣工作 —— 讓死亡進程四處遊蕩，而不是簡單地讓它們死亡並進入數字天堂，所以殭屍的存在表明了讓他們遺留於此的進程有一些缺陷。</p><p>一個簡單的方法來檢查你的系統是否有殭屍進程遺留，看看 <code>top</code> 命令的標題行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ top</span></span>
<span class="line"><span>top - 18:50:38 up 6 days, 6:36, 2 users, load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span>Tasks: 171 total, 1 running, 167 sleeping, 0 stopped, 3 zombie	\`&lt; ==\`</span></span>
<span class="line"><span>%Cpu(s): 0.0 us, 0.0 sy, 0.0 ni, 99.9 id, 0.1 wa, 0.0 hi, 0.0 si, 0.0 st</span></span>
<span class="line"><span>KiB Mem : 2003388 total, 250840 free, 545832 used, 1206716 buff/cache</span></span>
<span class="line"><span>KiB Swap: 9765884 total, 9765764 free, 120 used. 1156536 avail Mem</span></span></code></pre></div><p>可怕！上面顯示有三個殭屍進程。</p><h3 id="at-midnight" tabindex="-1">at midnight <a class="header-anchor" href="#at-midnight" aria-label="Permalink to “at midnight”">​</a></h3><p>有時會在萬聖節這麼説，死者的靈魂從日落開始遊蕩直到午夜。Linux 可以通過 <code>at midnight</code> 命令跟蹤它們的離開。用於安排在下次到達指定時間時運行的作業，<code>at</code> 的作用類似於一次性的 cron。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ at midnight</span></span>
<span class="line"><span>warning: commands will be executed using /bin/sh</span></span>
<span class="line"><span>at&gt; echo &#39;the spirits of the dead have left&#39;</span></span>
<span class="line"><span>at&gt; &lt;EOT&gt;</span></span>
<span class="line"><span>job 3 at Thu Oct 31 00:00:00 2017</span></span></code></pre></div><h3 id="守護進程" tabindex="-1">守護進程 <a class="header-anchor" href="#守護進程" aria-label="Permalink to “守護進程”">​</a></h3><p>Linux 系統也高度依賴守護進程 —— 在後台運行的進程，並提供系統的許多功能。許多守護進程的名稱以 “d” 結尾。這個 “d” 代表<ruby>守護進程<rt>daemon</rt></ruby>，表明這個進程一直運行並支持一些重要功能。有的會用單詞 “daemon” 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | grep sshd</span></span>
<span class="line"><span>root 1142 1 0 Oct19 ? 00:00:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span>root 25342 1142 0 18:34 ? 00:00:00 sshd: shs [priv]</span></span>
<span class="line"><span>$ ps -ef | grep daemon | grep -v grep</span></span>
<span class="line"><span>message+ 790 1 0 Oct19 ? 00:00:01 /usr/bin/dbus-daemon --system --address=systemd: --nofork --nopidfile --systemd-activation</span></span>
<span class="line"><span>root 836 1 0 Oct19 ? 00:00:02 /usr/lib/accountsservice/accounts-daemon</span></span></code></pre></div><h3 id="萬聖節快樂" tabindex="-1">萬聖節快樂！ <a class="header-anchor" href="#萬聖節快樂" aria-label="Permalink to “萬聖節快樂！”">​</a></h3>`,26)),t("p",null,[s[2]||(s[2]=a("在 ",-1)),n(e,{href:"https://www.facebook.com/NetworkWorld/"},{default:i(()=>[...s[0]||(s[0]=[a("Facebook",-1)])]),_:1}),s[3]||(s[3]=a(" 和 ",-1)),n(e,{href:"https://www.linkedin.com/company/network-world"},{default:i(()=>[...s[1]||(s[1]=[a("LinkedIn",-1)])]),_:1}),s[4]||(s[4]=a(" 上加入 Network World 社區來對主題進行評論。",-1))]),s[19]||(s[19]=t("hr",null,null,-1)),t("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3235219/linux/scary-linux-commands-for-halloween.html"},{default:i(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3235219/linux/scary-linux-commands-for-halloween.html",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[8]||(s[8]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const w=l(c,[["render",h]]);export{y as __pageData,w as default};
